                s = s.Replace("Oh, it is,\nit is!\nCongratulations, Professor Harebrayne!", "Oh oui,\nmille fois oui !\nToutes nos félicitations, professeur Lonron !");
                s = s.Replace("Mr Naruhodo...\nMiss Susato...", "M. Naruhodo...\nMlle Susato...");
                s = s.Replace("I am truly...\ntruuuu\nly...", "Je vous suis tellement...\ntelleeeement...");
