                s = s.Replace("AAAAAAH!\nRight now,\nyou know...\nif I had that research\ngrant money...", "AAAAAAH !\nSi seulement,\nsi seulement j'avais ces fonds de recherche\navec moi...");
                s = s.Replace("AAAAAAH!\nI'd give the whole lot to you!\nEvery penny!", "AAAAAAH !\nJe vous donnerais l'intégralité de la bourse !\nJusqu'au dernier penny !");
                s = s.Replace("Well...\nthat's very kind, but...\nI'm just a student,\nso...", "Eh bien...\nc'est fort aimable, mais...\nje ne suis qu'un étudiant,\nalors...");
                s = s.Replace("We don't need any financial reward.\nYour acquittal is more than enough.", "Nous n'avons besoin d'aucune récompense matérielle.\nVotre acquittement nous comble de joie.");
                s = s.Replace("Oh dear...\nOh what can\nI do...?\nAha!", "Grand Dieu...\nMais que puis-je\ndonc faire... ?\nEurêka !");
                s = s.Replace("How about this?\nAs a memento?\nThe paper about my hypothesis is inside!", "Que diriez-vous de ceci ?\nEn guise de souvenir ?\nLe manuscrit de ma théorie se trouve à l'intérieur !");
                s = s.Replace("Well,\njust as a memento then.\nThank you.", "Eh bien,\ncomme simple souvenir alors.\nMerci beaucoup.");
                s = s.Replace("I've been wondering, Professor...\n...what are you going to do now?", "Je me demandais, professeur...\n...que comptez-vous faire maintenant ?");
                s = s.Replace("Oh,\noh my...\nYes...\nWhat am I going to do?\nMy hypothesis and my great machine\nlie in ruins...", "Oh,\nô ciel...\nOui...\nQue vais-je donc faire ?\nMa théorie et ma machine magistrale\nsont en ruines...");
                return s;
            };
            entryTranslators[@"BB\script\output\_sce02_c308_0000_eng#3"] = s => {
                s = s.Replace("But still,\nit's been too long since I was last in London,\nso\nperhaps I'll enjoy some sightseeing.", "Mais après tout,\ncela fait si longtemps que je n'étais venu à Londres,\nalors\nje pourrais peut-être en profiter pour visiter la ville.");
                s = s.Replace("I must explore the Great Exhibition whilst I'm here, too,\nand see if new inspiration hits me.", "Je dois absolument visiter l'Exposition universelle,\net voir si une nouvelle inspiration s'éveille en moi.");
                s = s.Replace("Oh yes,\nthat's a wonderful idea,\nI–", "Oh oui,\nc'est une idée formidable, je–");
                s = s.Replace("I can't\nallow that.", "Je ne saurais\nle permettre.");
                s = s.Replace("L-\nLord van Zieks!\nWhat are you doing in here?", "L-\nLord Van Peers !\nQue faites-vous ici ?");
                s = s.Replace("Barok!", "Drake !");
                s = s.Replace("I'm sorry you had to go through that,\nAlbert.", "Je suis navré que tu aies dû subir pareille infamie,\nSamba.");
                s = s.Replace("Well,\nif I'm honest...\nit,\nit was terrifying!", "Eh bien,\npour être tout à fait franc...\nc'était terrifiant !");
                s = s.Replace("You were like a great demon behind your bench there,\nsnarling down on your prey!", "Tu ressemblais à un véritable démon derrière ton banc,\ngrognant sur ta proie !");
                s = s.Replace("You're one of the few true friends I have.", "Tu es l'un des rares et authentiques amis que je possède en ce monde.");
                s = s.Replace("I couldn't leave it to anybody else to handle the\nprosecution...\nor the defence.", "Je ne pouvais confier à personne d'autre la charge de\nl'accusation...\nni celle de la défense.");
                s = s.Replace("Sorry?\n(Or\nthe defence\n?\nDid,\ndid I just hear that right?)", "Pardon ?\n(Ou\nla défense\n?!\nAi-je bien entendu ?!)");
                s = s.Replace("I always knew that you had my best interests at heart,\ndon't worry.", "J'ai toujours su que tu veillais sur moi, ne t'en fais pas.");
                s = s.Replace("Ah,\nhow about you show me around while I'm here in\ntown?\nIt's been a long time since we left university.\nWe have a lot to catch up on.", "Dis-moi,\net si tu me faisais visiter la ville tant que je suis là ?\nNos années universitaires remontent à si loin.\nNous avons tant d'anecdotes à partager.");
                s = s.Replace("Listen,\nAlbert...\n...in a few days,\nyour acquittal will be made official.\nWhen that happens...", "Écoute-moi,\nSamba...\n...d'ici quelques jours,\nton acquittement sera officiellement entériné.\nDès cet instant...");
                s = s.Replace("...you must head straight to Dover.\nI'll accompany you.", "...tu dois filer directement vers Douvres.\nJe t'escorterai moi-même.");
                s = s.Replace("What?", "Comment ?!");
                s = s.Replace("From there,\nyou'll cross the Channel and make your way\nback to Germany.\nI've already purchased the tickets.", "De là,\ntu traverseras la Manche pour regagner\nl'Allemagne sans attendre.\nJ'ai déjà acheté tes billets.");
                s = s.Replace("But,\nbut no!\nHold on a minute, Barok!\nWhat about the Great Exhibition?\nThis is the chance of a\nlifetime for me!\nI want to look around.", "Mais...\nmais non !\nAttends une minute, Drake !\nEt l'Exposition universelle alors ?\nC'est la chance de toute une vie pour moi !\nJe veux explorer les pavillons !");
                s = s.Replace("No,\nno sightseeing, Albert.\nGive up on the idea.", "Non,\npas de tourisme, Samba.\nOublie cette idée sur-le-champ.");
                s = s.Replace("Ugh...\nS-\nSometimes\nit's hard to see any warmth in those\neyes,\nBarok...", "Gloups...\nP-\nParfois,\nil est difficile de déceler la moindre chaleur dans ton regard,\nDrake...");
                s = s.Replace("Um,\nLord van Zieks...\n...what's all this about?", "Euh,\nLord Van Peers...\n...pourquoi tout cela ?");
                s = s.Replace("A necessary precaution.", "Une précaution indispensable.");
                s = s.Replace("Yes,\nI...\nthink I understand.", "Oui,\nje...\ncrois comprendre.");
                s = s.Replace("You do?", "Vraiment ?");
                s = s.Replace("Well,\nIris told me that when you met Lord van Zieks at\nhis office\nsome days ago...\n...he asked how Mr Natsume was doing.", "Eh bien,\nIris m'a raconté que lorsque vous avez vu Lord Van Peers à\nson bureau il y a quelques jours...\n...il s'est enquis des nouvelles de M. Sôseki.");
                s = s.Replace("Yes,\nthat's right!\nI remember being surprised at the time...\nand thinking it was nice of him to ask.", "Oui,\nc'est vrai !\nJe me souviens avoir été surpris à ce moment-là...\net d'avoir trouvé son geste très délicat.");
                s = s.Replace("The point is...\nMr Natsume\nis\nstill alive\nand well!", "Ce que je veux dire...\nc'est que M. Sôseki\nest\ntoujours bien vivant\net en parfaite santé !");
                s = s.Replace("Even though\nit's been more than six months now since\nhe stood trial with the Reaper as the prosecutor.", "Bien que cela fasse plus de six mois désormais\nqu'il a été jugé avec le Procureur Démon à l'accusation.");
                s = s.Replace("Ah!\nYou,\nyou mean...\n...the Reaper's influence\ndoesn't stretch\noverseas\n?", "Ah !\nVous...\nvoulez dire...\n...que la malédiction du Démon de l'Old Bailey\nne franchit pas\nles frontières maritimes\n?!");
                s = s.Replace("Those in the Reaper's sights\nmeet their ends days\nor\nsometimes months after their acquittal.\nThat's been the pattern up to now.", "Ceux que le Démon fauche\npérissent quelques jours,\nou parfois quelques mois après leur acquittement.\nTelle a toujours été la règle funeste jusqu'ici.");
                s = s.Replace("But of course,\nwe know that both Mr Natsume and Gina\nwere completely innocent.", "Mais bien évidemment,\nnous savons que M. Sôseki et Gina\nétaient tous deux parfaitement innocents.");
                s = s.Replace("True.\nAnd perhaps that\ngoverns the Reaper's actions.\nThe truly\ninnocent\nare\nspared\n.", "C'est exact.\nEt peut-être est-ce là\nla loi secrète du Démon.\nLes véritables\ninnocents\nsont\népargnés\n.");
                s = s.Replace("But I don't want to take any chances\nwith a close personal\nfriend.", "Mais je refuse de courir le moindre risque\nlorsqu'il s'agit d'un ami\naussi cher.");
                s = s.Replace("B-\nB-\nBarok...", "D-\nD-\nDrake...");
                s = s.Replace("Like the moustached Nipponese...\nthis man should leave\nthe country without delay.", "Tout comme le moustachu nippon...\ncet homme doit quitter le royaume\nsans le moindre délai.");
                return s;
            };
            entryTranslators[@"BB\script\output\_sce02_c308_0000_eng#4"] = s => {
                s = s.Replace("That's why...\nI'm packing him off to Germany at once!", "Voilà pourquoi...\nje l'expédie séance tenante en Allemagne !");
                s = s.Replace("R-\nRight...\n(Does your friend-shaped package\nget\nany say in it...?)", "C-\nCompris...\n(Et ce colis aux allures de grand savant\na-t-il son mot\nà dire dans l'histoire...?)");
                s = s.Replace("Goodness!\nWas this your intention all along then,\nLord\nvan Zieks?", "Ciel !\nÉtait-ce donc votre intention depuis le départ,\nLord Van Peers ?");
                s = s.Replace("(In court,\nwhere people think of him as the Reaper,\nthis\nman seems absolutely merciless...\nand yet...)\n(...sometimes\nI feel as though I don't understand him at all.)", "(Au tribunal,\noù tous le redoutent comme le Démon de la justice,\ncet homme paraît impitoyable...\net pourtant...)\n(...parfois,\nj'ai le sentiment de ne pas le comprendre du tout.)");
                s = s.Replace("It's time to go, Albert.\nBack to the prison for the time being.", "L'heure est venue, Samba.\nRetournons à la prison pour l'instant.");
                s = s.Replace("Ah,\nyes,\nalright.\nWell then,\nMr Naruhodo...\n...thank you so much for everything!", "Ah,\noui,\nentendu.\nEh bien,\nM. Naruhodo...\n...merci du fond du cœur pour tout !");
                s = s.Replace("Not at all, Professor!\nIt was a pleasure getting to know you!", "Tout le plaisir était pour nous, professeur !\nCe fut un honneur de faire votre connaissance !");
                s = s.Replace("Best wishes,\nProfessor Harebrayne.", "Tous nos vœux vous accompagnent,\nprofesseur Lonron.");
                s = s.Replace("Well,\nonce the dust has settled...\nyou MUST come and visit\nme in Germany!\nAnyway,\ngoodbye for now!", "Promis,\nune fois que tout sera rentré dans l'ordre...\nvous DEVREZ venir me voir\nen Allemagne !\nEn attendant,\nau revoir !");
                s = s.Replace("Now,\nmy Nipponese friend...\nOh!\nYes?\n(I thought you'd gone too...)\n...we have matters to discuss.\nCan you spare me some time?", "À présent,\nmon cher confrère nippon...\nOh !\nOui ?\n(Je croyais que vous étiez parti vous aussi...)\n...nous avons à nous entretenir.\nPourriez-vous m'accorder un instant ?");
                s = s.Replace("You want to talk\nwith me?", "Vous souhaitez parler...\navec moi ?");
                s = s.Replace("I'll be waiting in the courtroom in ten minutes.", "Je vous attends dans la salle d'audience d'ici dix minutes.");
                s = s.Replace("(Well that was strange.)\n(For some reason\nI didn't get that sense of impending\ndoom as he walked away this time.)", "(Voilà qui était inattendu.)\n(Pour une raison obscure,\nje n'ai pas ressenti ce frisson glacial lorsqu'il s'est éloigné cette fois-ci.)");
                s = s.Replace("(The enigma,\nBarok van Zieks...)\n(What does he want to discuss,\nI wonder?)\n(The answer awaits in the courtroom, I suppose.\nHere goes then...)", "(Une véritable énigme,\nce Drake Van Peers...)\n(De quoi peut-il bien vouloir me parler ?)\n(La réponse m'attend dans le prétoire, j'imagine.\nAllons-y...)");
                return s;
            };
            entryTranslators[@"BB\script\output\_sce02_c308_0010_eng#2"] = s => {
                s = s.Replace("24th October, 4:58 p.m.", "24 octobre, 16 h 58");
                s = s.Replace("The Old Bailey Courtroom", "Old Bailey, salle d'audience");
                s = s.Replace("So,\nare you satisfied?\nYou saved a guileless scientist from\na great injustice.", "Alors,\nêtes-vous satisfait ?\nVous avez préservé un savant candide\nd'une effroyable injustice.");
                s = s.Replace("Um...\nyes!\nI think so.\nI'm relieved, at least,\nthat the man's innocence could be\nproven.", "Euh...\noui !\nJe le pense.\nJe suis soulagé, à tout le moins,\nque son innocence ait pu être\néclatante.");
                s = s.Replace("Anyway...\n...I imagine you've been wondering\nwhere my animosity\ntowards you Nipponese comes from.", "Quoi qu'il en soit...\n...j'imagine que vous vous demandez depuis toujours\nd'où provient mon animosité viscérale\nenvers votre peuple nippon.");
                s = s.Replace("Well,\nat first I thought you just didn't like me.\nI imagined you saw me as a pretentious child from an\nunimportant land,\nwho had no business being here.", "Eh bien,\nau début je pensais simplement que vous ne m'aimiez pas.\nJ'imaginais que vous voyiez en moi un freluquet prétentieux venu d'une\ncontrée lointaine,\nqui n'avait rien à faire dans ce prétoire.");
                s = s.Replace("But now\nI think differently.", "Mais désormais,\nj'ai changé d'avis.");
                s = s.Replace("You clearly know our ways.\nSo I would guess\nthat some specific incident\nled to your\nthorough dislike of my race.\nWill you tell me what happened,\nplease?", "Vous connaissez nos coutumes.\nJ'en déduis donc\nqu'un événement bien particulier\na fait naître cette\nrancœur tenace envers les Japonais.\nMe direz-vous ce qu'il s'est passé,\nje vous prie ?");
                s = s.Replace("The Professor...", "Le Démon Assassin...");
                s = s.Replace("I thought I'd never hear that name in this courtroom\nagain, to be honest.", "Je pensais ne plus jamais réentendre ce nom maudit dans ce tribunal,\npour être tout à fait honnête.");
                s = s.Replace("He,\nhe took your brother's life...", "C'est...\nc'est lui qui a ôté la vie à votre frère...");
                s = s.Replace("Klint.\nMy brother was Klint van Zieks.", "Klimt.\nMon frère aîné était Klimt Van Peers.");
                s = s.Replace("Sixteen years ago,\nwhen I was still just in my teens...\n...he was already the Director of Prosecutions,\nand a key\nmember of the judiciary.\nI looked up to him.\nHe was everything I aspired to be.", "Il y a seize ans,\nalors que je n'étais qu'un jeune adolescent...\n...il était déjà procureur général,\net une figure centrale\nde notre système judiciaire.\nJe le vénérais.\nIl incarnait tout ce dont je rêvais de devenir.");
                s = s.Replace("He was involved in the establishment of justice systems\nin foreign countries, as well.\nThere were exchange programmes between Britain and\nother nations then too,\nto share knowledge and ideas.\nAs part of one of those programmes...\n...three judicial students came to Britain from your\nhomeland,\nthe Empire of Japan.", "Il a également contribué à l'édification de systèmes judiciaires\nà l'étranger.\nDes programmes d'échange existaient déjà entre la Grande-Bretagne\net d'autres nations,\npour partager savoirs et principes juridiques.\nDans le cadre de l'une de ces délégations...\n...trois étudiants en droit sont arrivés en Angleterre depuis votre\npatrie,\nl'Empire du Japon.");
                s = s.Replace("Oh!\nIf it was sixteen years ago,\nthen...\none of them could have\nbeen my father...", "Oh !\nSi c'était il y a seize ans,\nalors...\nl'un d'eux pouvait être\nmon père...");
                s = s.Replace("Of course,\nI remember Doctor Mikotoba well.", "Naturellement,\nje me souviens fort bien du Dr Mikotoba.");
                s = s.Replace("I had no idea...", "Je n'en avais aucune idée...");
                s = s.Replace("I was a minor at the time,\ntraining at the Prosecutor's\nOffice.\nOne day\nKlint introduced me to the three visiting\nNipponese.", "J'étais encore mineur à l'époque,\nen apprentissage au sein du parquet.\nUn jour,\nKlimt m'a présenté les trois émissaires\nnippons.");
                s = s.Replace("So...\nyou've actually met my father...", "Ainsi...\nvous avez réellement rencontré mon père...");
                s = s.Replace("He and his colleagues were polite and amicable.\nThey\nwere adept at their work\nand exacting in their standards.\nIt was my first encounter with the Nipponese spirit,\nand\nit made a very great impression upon me.", "Lui et ses confrères étaient d'une politesse et d'une amabilité exquises.\nIls\nétaient remarquablement doués\net d'une exigence morale sans faille.\nCe fut mon premier contact avec l'âme nipponne,\net\nelle m'inspira un profond respect.");
                s = s.Replace("But six years later...\nThat's when it happened.\nThe investigation was going nowhere.\nThere were no\nsuspects, even.\nJust an ever-growing list of victims.\nAnd in the end...\nmy brother became one of them.\nThe last in fact,\nbefore the case was finally resolved.", "Mais six ans plus tard...\nC'est là que l'horreur a frappé.\nL'enquête piétinait complètement.\nIl n'y avait pas le moindre\nsuspect.\nSeulement une liste funeste de victimes qui ne cessait de s'allonger.\nEt à la fin...\nmon frère a été l'une d'elles.\nLa toute dernière,\navant que l'affaire ne soit enfin résolue.");
                s = s.Replace("I'm so sorry, Lord van Zieks.\nTruly...", "Je suis tellement navré, Lord Van Peers.\nSincèrement...");
                s = s.Replace("Klint was always ready to put his life on the line for\njustice anyway.\nSo he wouldn't have wanted it any other way.\nHe lost his\nlife to the killer,\nbut it was his victory in the end.", "Klimt était de toute façon prêt à offrir sa vie pour la justice.\nIl n'aurait voulu d'autre destin.\nIl a succombé sous les coups\ndu monstre,\nmais c'est lui qui a triomphé à la fin.");
                s = s.Replace("For me personally, though,\nit was a great loss.\nI found myself\nin a very dark place indeed.", "Pour moi personnellement,\nce fut une déchirure insondable.\nJ'ai sombré\ndans les plus sombres abîmes.");
                s = s.Replace("When I finally found out the killer's identity...\n...the reason why no one had been able to catch the man\nsooner ceased to be such a mystery.\nHe'd\nbeen\nhiding in plain sight\nall the time.", "Lorsque j'ai enfin découvert l'identité de l'assassin...\n...la raison pour laquelle nul n'avait pu le capturer plus tôt\na cessé d'être un mystère.\nIl se cachait\naux yeux de tous,\ndepuis le premier jour.");
                s = s.Replace("In plain sight?", "Aux yeux de tous ?");
                s = s.Replace("Are you aware of political events ten years ago?\nIt was a period of extremely sensitive diplomacy between\nthe British and Japanese empires.", "Êtes-vous au fait du contexte géopolitique d'il y a dix ans ?\nC'était une période de pourparlers diplomatiques d'une sensibilité extrême\nentre les empires britannique et japonais.");
                s = s.Replace("A new treaty\nwas being forged,\nI think?", "Un nouveau traité\nétait en cours de négociation,\nme semble-t-il ?");
                s = s.Replace("Correct.\nThe Anglo-Japanese Treaty of Friendship and\nNavigation was being concluded.\nThe leaders of both countries were deep in extensive\npolitical discussions.", "Exact.\nLe traité anglo-japonais de commerce et de navigation\nétait sur le point d'être ratifié.\nLes dirigeants des deux nations étaient engagés dans de\ntranscendantes négociations.");
                s = s.Replace("Which is why\nthis particular killer's appearance in court\nwas conducted as a closed trial.\nIf the British public had known the identity of the killer...\n...not only would the treaty have been in jeopardy...\nbut\nour two nations could very well have ended up at war.", "Voilà pourquoi\nle procès de ce boucher sanguinaire\ns'est tenu strictement à huis clos.\nSi le peuple britannique avait découvert l'identité du coupable...\n...non seulement le traité aurait volé en éclats...\nmais\nnos deux empires auraient fort bien pu basculer dans la guerre.");
                s = s.Replace("What?!\nA,\na war...\nbetween Britain and Japan?", "Quoi ?!\nUne...\nune guerre...\nentre la Grande-Bretagne et le Japon ?!");
                s = s.Replace("But that would mean...\nOh my!\nYou mean to say\nthe Professor was...", "Mais cela signifierait...\nGrand Dieu !\nVoulez-vous dire que\nle Démon Assassin était...");
                return s;
            };
            entryTranslators[@"BB\script\output\_sce02_c308_0020_eng#2"] = s => {
                s = s.Replace("When the trial reached its conclusion earlier,\nI thought to myself,\n‘Yes,\nit's time.’", "Lorsque ce procès a rendu son verdict tout à l'heure,\nje me suis dit :\n« Oui,\nl'heure est venue. »");
                s = s.Replace("Time for you to come face to face\nwith this\nhideous\nmonster.", "L'heure est venue pour vous de faire face\nà ce\nmonstre\nhydre.");
                s = s.Replace("Eh...?", "Hein... ?");
                s = s.Replace("I borrowed the key for the mask\nfrom the\nproprietress of the waxwork museum.", "J'ai emprunté la clé de ce masque\nà la\ndirectrice du musée de cire.");
                s = s.Replace("So see for\nyourselves now.\nConfirm it with your own\neyes:\nthe truth that's been hidden\nthis past decade.", "Voyez donc par\nvous-mêmes à présent.\nConstatez-le de vos propres\nyeux :\nla terrifiante vérité dissimulée\ndepuis dix longues années.");
                s = s.Replace("Th...\nThat's\nthe Professor?!", "C-...\nC'est lui\nle Démon Assassin ?!");
                s = s.Replace("Yes...\nthat's him.", "Oui...\nc'est bien lui.");
                s = s.Replace("...Until now...\nthe thought never even crossed my mind...", "...Jusqu'à cet instant...\njamais pareille pensée n'avait effleuré mon esprit...");
                s = s.Replace("...that the mass murderer\nwhose crimes\nshook\nBritain\nas never before...", "...que le tueur sanguinaire\ndont les atrocités\navaient fait trembler la Grande-Bretagne\ncomme jamais auparavant...");
                s = s.Replace("...was\nJapanese!", "...était\njaponais !");
                s = s.Replace("W-\nWait a minute!\nThat face...", "A-\nAttendez un instant !\nCe visage...");
                s = s.Replace("I feel as though...\nI've seen it somewhere...\nIt's strangely familiar...", "J'ai l'impression...\nde l'avoir déjà vu quelque part...\nIl m'est étrangement familier...");
                s = s.Replace("Fa...\nFather...", "Pè-...\nPère...");
                s = s.Replace("Wha...?\n‘Father’?", "Quoi... ?!\n« Père » ?!");
                return s;
            };
            entryTranslators[@"BB\script\output\_sce02_c308_0020_eng#3"] = s => {
                s = s.Replace("Kazuma!", "Kazuma !");
                s = s.Replace("(My best friend,\nKazuma Asogi...)", "(Mon meilleur ami,\nKazuma Asogi...)");
                s = s.Replace("(After a whole year...\nfinally,\nhis memories returned...)", "(Après une année entière d'amnésie...\nenfin,\nsa mémoire est revenue...)");
                s = s.Replace("(...as he stood there before me...)", "(...alors qu'il se tenait là devant moi...)");
                return s;
            };
            entryTranslators[@"BB\script\output\_sce02_c308_0020_eng#4"] = s => {
                s = s.Replace("Ryunosuke...", "Ryunosuke...");
                s = s.Replace("Hello again...\n...my friend.", "Te revoilà...\n...mon ami.");
                s = s.Replace("Kazuma-sama!", "Monsieur Kiyô !");
                s = s.Replace("Judicial Assistant Mikotoba...", "Chère assistante juridique Mikotoba...");
                s = s.Replace("...It's been\na very long road.\nThank you.", "...Le chemin a été\nsi long et tortueux.\nMerci.");
                s = s.Replace("Thank you\nfor guiding my friend\nhere\nwhen I could not.", "Merci\nd'avoir guidé mon ami jusqu'ici\nalors que j'en étais incapable.");
                s = s.Replace("It...\nit was an honour.", "Ce... ce fut un honneur infini.");
                s = s.Replace("I knew you\nwouldn't die that easily,\nKazuma.", "Je savais que tu ne mourrais pas si facilement,\nKazuma.");
                s = s.Replace("...I owe you thanks,\ntoo.\n...for taking good care of that\nin my absence.", "...Je te dois d'immenses remerciements\nà toi aussi.\n...Pour avoir pris grand soin d'elle\nen mon absence.");
                s = s.Replace("Hm?\n...Oh!", "Hum ?\n...Oh !");
                s = s.Replace("(Karuma,\nthe great blade of the Asogi clan,\npassed down\nthrough the generations...)", "(Karuma,\nla vénérable lame du clan Asogi,\ntransmise fidèlement\nde génération en génération...)");
                s = s.Replace("(When we left Japan,\nthis sword\nwas at my\nfriend's side.)", "(Lorsque nous avons quitté le Japon,\ncette lame\nétait au flanc de mon ami.)");
                s = s.Replace("(A Japanese man's katana is his soul.\nAnd he couldn't be parted from it.)", "(Pour un samouraï, le katana est son âme même.\nEt il ne pouvait s'en séparer.)");
                s = s.Replace("(But then,\nwhen the incident happened...)", "(Mais alors,\nlorsque le drame est survenu...)");
                s = s.Replace("(...it was Susato-san's wish\nthat I inherit the sword.)", "(...Susato-san a souhaité\nque j'hérite de cette lame.)");
                s = s.Replace("(And I've kept it with me\never since...\nalong with\nmy memories\nof the friendship we shared.)", "(Et je l'ai gardée à mes côtés\ndepuis ce jour...\navec le souvenir indélébile\nde notre amitié fraternelle.)");
                s = s.Replace("With this by my side,\nI always felt that you were\nwatching over me somehow.", "En la portant à mon côté,\nj'avais le sentiment que tu veillais sur moi d'une certaine façon.");
                s = s.Replace("I've made it\nat last...\nFather.", "J'y suis parvenu...\nenfin...\nPère.");
                s = s.Replace("Are you saying...?\nSurely not!\nYou mean...y-\nyou knew all this time?!", "Êtes-vous en train de dire... ?\nCe n'est pas possible !\nTu veux dire... que tu le savais depuis le début ?!");
                s = s.Replace("(I'm looking at it,\nbut\nI still\ncan't believe it...)", "(Je le vois de mes yeux,\nmais\nje n'arrive toujours pas à y croire...)");
                s = s.Replace("(This\nmass murderer...\nis\nKazuma's\nfather!)", "(Ce\nmeurtrier sanguinaire...\nest\nle père de Kazuma !)");
                return s;
            };
