            entryTranslators[@"BB\script\output\_sce02_c308_0020_eng#6"] = s => {
                s = s.Replace("K-\nKazuma-sama...", "M-\nMonsieur Kiyô...");
                s = s.Replace("Ryunosuke...\n...we have much\nto talk about,\nbut now\nis not the time.", "Ryunosuke...\n...nous avons tant de choses\nà nous dire,\nmais l'heure n'est pas venue.");
